  codigo: 'C-1',
  listaProblemas: [{ titulo: 'Problem', tiempo: 1, memoria: 256 }],
  archivoZip: new File(['zip'], 'cases.zip'),
}

const wrapper = ({ children }: PropsWithChildren) => (
  <QueryClientProvider
    client={
      new QueryClient({
        defaultOptions: {
          queries: { retry: false },
          mutations: { retry: false },
        },
      })
    }
  >
    {children}
  </QueryClientProvider>
